row_rules.VN_MAINTRNS:
if inserting then
  :new.alt_key := :new.trns_id || '-' || :new.trns_serial;
end if;
if nvl(:new.link_flag, 0) = 0 and :new.post_system is null then
  if inserting then
    :new.pay_method := nvl(:new.pay_method, 5);
    :new.bill_pay_method := nvl(:new.bill_pay_method, 1);
    :new.pay_type_code := nvl(:new.pay_type_code, app_rules_vn.default_pay_type);
    :new.resp_code := nvl(:new.resp_code, app_rules_vn.supplier_resp(:new.supplier_id));
    :new.description_e := app_rules_vn.payment_desc_e(:new.trns_id, :new.description_e, :new.doc_no, :new.pay_method, :new.acc_post_date);
  end if;
  if :new.inv_value is not null and (inserting
     or app_rules_vn.differs(:new.inv_value, :old.inv_value) = 1 or app_rules_vn.differs(:new.tax_value2, :old.tax_value2) = 1
     or app_rules_vn.differs(:new.supplier_id, :old.supplier_id) = 1 or app_rules_vn.differs(:new.trns_date, :old.trns_date) = 1) then
    app_rules_vn.calc_tax(:new.trns_id, :new.supplier_id, :new.trns_date, :new.inv_value, :new.tax_code1, :new.tax_value1);
    :new.total_value := app_rules_vn.total_with_tax(:new.trns_id, :new.supplier_id, :new.inv_value, :new.tax_value1, :new.tax_value2);
  end if;
end if;

row_rules.VN_MAINTRNS_SUPP_ACC:
app_rules_vn.acc_line(:new.acc_number, :new.acc_val, :new.cost_center, :new.cost_center2);
if inserting then
  :new.acc_memo := app_rules_vn.supp_acc_memo(:new.trns_id, :new.trns_serial, :new.acc_memo);
end if;
